import{_ as o,l,o as e,c as n,v as t,p as m,x as r,d,i as h,S as s}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"初始化为何需要","description":"","frontmatter":{"title":"初始化为何需要","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/why-init.md","filePath":"llm/why-init.md","lastUpdated":1789023840000}'),p={name:"llm/why-init.md"};function _(E,a,A,c,B,u){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="初始化为何需要" tabindex="-1">初始化为何需要 <a class="header-anchor" href="#初始化为何需要" aria-label="Permalink to &quot;初始化为何需要&quot;">​</a></h1><div class="epigraph"><p>随机权重的尺度决定前向方差沿深度是爆还是灭；初始化不是「随便给个数」，而是把每层增益放在 $1$ 附近。</p><footer>—— 据 Glorot &amp; Bengio, Understanding the Difficulty of Training Deep Feedforward Neural Networks, AISTATS 2010；He et al., Delving Deep into Rectifiers, ICCV 2015 整理</footer></div><p><a href="/llm/activation-relu-saturation">激活：ReLU 与饱和</a>选定了 \\(\\sigma\\)。本课不重画分段线性。缺口是：\\(W\\) 若按过大的方差抽取，前向 \\(\\|h\\|\\) 爆炸、激活饱和；过小则信号灭掉、反向一并消失。优化课的 \\(\\eta\\) 管一步有多长，不管第一步站在哪。方法是按扇入 / 扇出设 \\(\\mathrm{Var}(W_{ij})\\)，使每层输出坐标的方差大致保持。残差与 LayerNorm 会放宽这条，但不会让「全零或过大」变得合法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全零初始化使对称的神经元收到同一梯度，永远无法分化——对称性打破必须靠随机。但随机的尺度是自由量。考虑一层 \\(y=Wx\\)，\\(x\\) 各维独立、方差 \\(v\\)，则 \\(\\mathrm{Var}(y_i)\\approx d_{\\mathrm{in}}\\,\\mathrm{Var}(W_{ij})\\,v\\)。要 \\(\\mathrm{Var}(y)\\approx\\mathrm{Var}(x)\\)，需 \\(\\mathrm{Var}(W_{ij})\\approx 1/d_{\\mathrm{in}}\\)。ReLU 丢掉约一半能量，He 初始化改成 \\(2/d_{\\mathrm{in}}\\)。缺口不是再选一种 \\(\\sigma\\)，而是承认深度把每层方差误差同样做成指数，与梯度连乘是同一类 \\(\\rho^L\\)。</p><p>「从预训练加载」也是初始化：后层看见的尺度已经被前层与归一化钉死。从零训练时没有这份礼物。本课针对从零开始的前馈栈。</p><h3 id="初始化不是把权重归一化成单位范数这么一次" tabindex="-1">初始化不是把权重归一化成单位范数这么一次 <a class="header-anchor" href="#初始化不是把权重归一化成单位范数这么一次" aria-label="Permalink to &quot;初始化不是把权重归一化成单位范数这么一次&quot;">​</a></h3><p>把每行除以范数，只能管住起始瞬间的 \\(\\|W\\|_2\\)，训练几步后尺度由更新决定。初始化理论管的是<strong>起点与早期</strong>的信号传播，不是全程约束。全程约束是权重衰减、LayerNorm、残差。把初始化理解成「替代归一化层」，后课会显得重复。相反：初始化错了，归一化也救不了已经饱和或已经 NaN 的第一步。</p><p><span class="marginnote">偏置通常初值为 \\(0\\)。输出层有时按类先验设 \\(b\\)，使初始 softmax 接近数据频率，减少早期交叉熵的无谓大梯度。那是细节；本课的主杠杆仍是 \\(W\\) 的方差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Glorot（Xavier）：均匀或高斯，方差 \\(2/(d_{\\mathrm{in}}+d_{\\mathrm{out}})\\)，兼顾正向扇入与反向扇出。He：ReLU 用 \\(2/d_{\\mathrm{in}}\\)。实现上 <code>kaiming_uniform_</code> 一类按层类型与 \\(\\sigma\\) 查表。嵌入表常用更小的标准差，避免初始查找向量过大。所有方案都假定坐标近似独立、激活近似按期望工作；深度极大或高度相关时只是粗路标。</p>',11)),(e(),m(s,null,{default:r(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAN%5B%22%E6%89%87%E5%85%A5%20d_in%22%5D%20--%3E%20VAR%5B%22%E8%AE%BE%E5%AE%9A%20Var%20W%22%5D%0A%20%20SIG%5B%22%E6%BF%80%E6%B4%BB%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20VAR%0A%20%20VAR%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%E6%96%B9%E5%B7%AE%E6%B2%BF%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20FWD%20--%3E%7C%22%E7%BA%A6%201%22%7C%20OK%5B%22%E5%8F%AF%E8%AE%AD%E8%B5%B7%E7%82%B9%22%5D%0A%20%20FWD%20--%3E%7C%22%E5%81%8F%E7%A6%BB%201%20%E7%9A%84%20L%20%E6%AC%A1%E6%96%B9%22%7C%20BAD%5B%22%E9%A5%B1%E5%92%8C%E6%88%96%E7%81%AD%E6%8E%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>初始化把每层的典型增益放到 \\(1\\) 附近，使 \\(\\rho^L\\) 在早期不立刻崩。它不保证训练过程中增益一直为 \\(1\\)：那要靠残差的恒等支路、靠归一化把激活重新拉回。但若起点已经饱和，梯度从第一步起就是 \\(0\\)，自适应优化器也无计可施。因此「先能把损失算出来且梯度非零」，是初始化的验收标准，比「符合某篇论文的精确系数」更优先。</p><p>与 \\(\\eta\\) 的耦合：初始梯度范数随 \\(W\\) 的尺度变。同一 \\(\\eta\\)，He 与过大方差的高斯不可互换。改初始化之后要重扫 \\(\\eta\\)，不要只改其中一项就比较曲线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导均值场的完整递归，不写正交初始化的全部定理。下一课<a href="/llm/params-depth-width">参数量：深度与宽度</a>假定网络已经能训起来，问容量花在加层还是加宽。后课默认：从零训练的线性层按激活选择扇入缩放；禁止全零权重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机初始化为了破对称；尺度为了让每层方差沿深度既不爆也不灭。</li><li>Glorot / He 把 \\(\\mathrm{Var}(W)\\) 设成 \\(1/d_{\\mathrm{in}}\\) 量级，ReLU 再乘 \\(2\\)。</li><li>初始化管起点，不替代全程的归一化与残差。</li><li>改初始化要连学习率一起看。</li><li>出处：Glorot &amp; Bengio, AISTATS 2010；He et al., ICCV 2015。</li></ul>',7))])}const x=o(p,[["render",_]]);export{D as __pageData,x as default};
